using System.Reflection;

// Explore Markout namespace and types
var types = typeof(Markout.MarkoutSerializerContext).Assembly.GetTypes()
    .Where(t => !t.Name.StartsWith("<") && t.IsPublic)
    .OrderBy(t => t.FullName)
    .ToList();

Console.WriteLine("=== Markout Public Types ===");
foreach (var t in types)
{
    Console.WriteLine($"{t.FullName}");
    if (t.IsInterface || t.IsAbstract) continue;

    var methods = t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)
        .Where(m => !m.IsSpecialName)
        .Take(5)
        .ToList();

    if (methods.Any())
    {
        foreach (var m in methods)
        {
            Console.WriteLine($"  - {m.Name}");
        }
    }
}
